diff --git a/netty/src/test/java/io/grpc/netty/NettyClientHandlerSensitivityDetectorTest.java b/netty/src/test/java/io/grpc/netty/NettyClientHandlerSensitivityDetectorTest.java
--- a/netty/src/test/java/io/grpc/netty/NettyClientHandlerSensitivityDetectorTest.java
