+    java.io.FileOutputStream fos = new java.io.FileOutputStream(file);
+    try {
+      fos.write(content.getBytes(StandardCharsets.UTF_8));
+    } finally {
+      fos.close();
+    }
+    return file;
+  }
+
+  private void updateTokenFile(File file, String content) throws IOException {
+    java.io.FileOutputStream fos = new java.io.FileOutputStream(file);
+    try {
+      fos.write(content.getBytes(StandardCharsets.UTF_8));
+    } finally {
+      fos.close();
+    }
+  }
