+    * @see io.grpc.ExperimentalApi
+    * @return result of supplier.
+    */
+  public <V> V supply(Supplier<V> supplier) {
+    Context previous = attach();
+    try {
+      return supplier.get();
+    } finally {
+      detach(previous);
+    }
+  }
