+    adjustTailSmallBufferCount();
+  }
+
+  private void adjustTailSmallBufferCount() {
+    if (tailSmallBufferCount > readableBuffers.size()) {
+      tailSmallBufferCount = readableBuffers.size();
+    }
   }

